mapper.select:
SELECT IFNULL((count(id)-SUM(sub.num=0)),0) AS a1, IFNULL((count(id)-SUM(sub.num=0)),0) AS a2, IFNULL(SUM(sub.num=0),0) AS a3, IFNULL(count(id),0) as a4 FROM( SELECT IFNULL(SUM(BLD.lampblack_data > 1 or BLD.matter_data > 5 or BLD.nmhc_data > 10),0) as num, BP.company_id as id FROM ${tableLampblack} BLD RIGHT JOIN base_point BP ON BLD.point_mac = BP.point_mac and BP.fid_region = #{fidRegion} WHERE 1=1
AND BLD.yyyymm = #{format}
AND BLD.yyyymmdd = #{formatDay}
GROUP BY BP.company_id ) sub

SELECT IFNULL(SUM(sub.num1),0) as a2, IFNULL(SUM(sub.num2),0) as a3, IFNULL(SUM(sub.num3),0) as a4, IFNULL(SUM(sub.num1+sub.num2+sub.num3),0) as a1 FROM( SELECT IFNULL(SUM(BLD.lampblack_data > 1),0) as num1, IFNULL(SUM(BLD.matter_data >5),0) as num2, IFNULL(SUM(BLD.nmhc_data > 10),0) as num3, BP.point_mac as id FROM ${tableLampblack} BLD RIGHT JOIN base_point BP ON BLD.point_mac = BP.point_mac and BP.fid_region = #{fidRegion} WHERE 1=1
AND BLD.yyyymm = #{format}
AND BLD.yyyymmdd = #{formatDay}
AND BP.company_id = #{companyId}
GROUP BY BP.point_mac ) sub

SELECT
    IFNULL(SUM(sub.num1),0) as a1,
    IFNULL(SUM(sub.num2),0) as a2,
    IFNULL(SUM(sub.num3),0) as a3
FROM(
SELECT
    IFNULL(SUM(BLD.lampblack_data > 1),0) as num1,
    IFNULL(SUM(BLD.matter_data >5),0) as num2,
    IFNULL(SUM(BLD.nmhc_data > 10),0) as num3
FROM ${tableLampblack} BLD
RIGHT JOIN base_point BP ON BLD.point_mac = BP.point_mac and BP.fid_region = #{fidRegion}
WHERE   1=1

        AND BLD.yyyymm = #{format}


        AND BLD.yyyymmdd = #{formatDay}


        AND BP.company_id = #{companyId}

) sub

SELECT  IFNULL(count(sub.t),0) as num
FROM (
    SELECT
    HOUR(BLD.create_time) as t,
    BLD.create_time
    FROM ${tableLampblack} BLD
    RIGHT JOIN base_point BP ON BLD.point_mac = BP.point_mac
    and BP.fid_region = #{fidRegion}
    and BP.company_id = #{companyId}
    WHERE  1=1
    AND BLD.yyyymmdd = #{formatDay}
    GROUP BY t
)sub
